#ifndef SCAMP_ADDRBITS_HPP
#define SCAMP_ADDRBITS_HPP

#include <cstdint>

// Address / prefix bit helpers.  Bits are numbered MSB first: bit 0 is the most
// significant bit of a 128 bit address (or of a 64 bit fragment word).

// Keep the top 'len' bits of a 128 bit value, clearing every host bit.
inline void top_bits(int len, uint64_t hi, uint64_t lo, uint64_t& nhi, uint64_t& nlo) {
    if (len <= 0) { nhi = 0; nlo = 0; return; }
    if (len >= 128) { nhi = hi; nlo = lo; return; }
    if (len >= 64) {
        nhi = hi;
        nlo = (len == 64) ? 0ull : ((lo >> (128 - len)) << (128 - len));
        return;
    }
    nhi = (hi >> (64 - len)) << (64 - len);
    nlo = 0;
}

// The n bits of (hi,lo) at positions [d, d+n).  n <= 64.
inline uint64_t bits128(uint64_t hi, uint64_t lo, int d, int n) {
    if (n <= 0) return 0;
    const uint64_t m = (n >= 64) ? ~0ull : ((1ull << n) - 1);
    if (d + n <= 64) return (hi >> (64 - d - n)) & m;
    if (d >= 64) return (lo >> (128 - d - n)) & m;
    const int hb = 64 - d;
    const int lb = n - hb;
    const uint64_t h = hi & ((1ull << hb) - 1);
    const uint64_t l = lo >> (64 - lb);
    return (h << lb) | l;
}

// Overwrite the n bits at positions [d, d+n) of (hi,lo) with v (n <= 64).
inline void set_bits128(uint64_t& hi, uint64_t& lo, int d, int n, uint64_t v) {
    if (n <= 0) return;
    const uint64_t m = (n >= 64) ? ~0ull : ((1ull << n) - 1);
    if (d + n <= 64) {
        const uint64_t sh = 64 - d - n;
        hi = (hi & ~(m << sh)) | ((v & m) << sh);
        return;
    }
    if (d >= 64) {
        const int sh = 128 - d - n;
        lo = (lo & ~(m << sh)) | ((v & m) << sh);
        return;
    }
    const int hb = 64 - d;
    const int lb = n - hb;
    const uint64_t hm = (1ull << hb) - 1;
    hi = (hi & ~hm) | ((v >> lb) & hm);
    const uint64_t lm = ((1ull << lb) - 1) << (64 - lb);
    lo = (lo & ~lm) | ((v & ((1ull << lb) - 1)) << (64 - lb));
}

// The six bit branch key consumed at global depth d.
inline uint8_t chunk6(uint64_t hi, uint64_t lo, int d) {
    return (uint8_t)(bits128(hi, lo, d, 6) & 0x3F);
}

// NI bitmap position of a local prefix of relative length l (<= 5) whose local
// value (the l bits following the node depth) is v.
inline int ni_position(int l, uint64_t v) { return (1 << l) + (int)v; }

// Bitmap position -> local relative length.
inline int ni_level(int pos) { return 63 - __builtin_clzll((unsigned long long)pos); }

#endif
