#ifndef SCAMP_FIB_HPP
#define SCAMP_FIB_HPP

#include "scamptrie_base.h"
#include <cstdint>
#include <vector>

// Exact model of the live FIB: the set of distinct normalized prefixes
// (length plus left aligned value) with last-write-wins next hops, together
// with the longest prefix match index used by the query operations.
class Fib {
public:
    Fib() { for (int i = 0; i < 129; ++i) len_count_[i] = 0; }

    void clear();

    // Insert / replace.  (hi,lo) may still carry host bits; len is 0..128.
    void put(uint8_t len, uint64_t hi, uint64_t lo, uint32_t hop);

    // Exact match of the normalized prefix of the given length.
    bool exact(uint8_t len, uint64_t hi, uint64_t lo, uint32_t& hop) const;

    // Longest stored prefix of length <= maxlen that matches (hi,lo).
    bool longest_within(uint8_t maxlen, uint64_t hi, uint64_t lo, uint32_t& hop) const;

    bool lpm(uint64_t hi, uint64_t lo, uint32_t& hop) const {
        return longest_within(128, hi, lo, hop);
    }

    uint32_t size() const { return count_; }

    template <class F> void for_each(F f) const {
        for (uint32_t i = 0; i < cap_; ++i)
            if (tbl_[i].len != EMPTY) f(tbl_[i].len, tbl_[i].hi, tbl_[i].lo, tbl_[i].hop);
    }

private:
    static const uint32_t EMPTY = 0xFFFFFFFFu;
    struct Slot {
        uint64_t hi, lo;
        uint32_t hop;
        uint32_t len;
        Slot() : hi(0), lo(0), hop(0), len(EMPTY) {}
    };
    std::vector<Slot> tbl_;
    uint32_t cap_ = 0, mask_ = 0, count_ = 0;
    uint32_t len_count_[129];

    uint32_t locate(uint32_t len, uint64_t hi, uint64_t lo) const;
    void store(uint32_t len, uint64_t hi, uint64_t lo, uint32_t hop);
    void grow();
};

// Bit helpers shared with the image code.
#include "addrbits.hpp"

#endif
