#include "fib.hpp"

static inline uint64_t mix64(uint64_t x) {
    x += 0x9e3779b97f4a7c15ull;
    x = (x ^ (x >> 30)) * 0xbf58476d1ce4e5b9ull;
    x = (x ^ (x >> 27)) * 0x94d049bb133111ebull;
    return x ^ (x >> 31);
}

static inline uint64_t key_hash(uint32_t len, uint64_t hi, uint64_t lo) {
    return mix64(mix64(hi * 0x100000001b3ull ^ lo) ^ ((uint64_t)len * 0x9e3779b97f4a7c15ull));
}

void Fib::clear() {
    for (uint32_t i = 0; i < cap_; ++i) tbl_[i] = Slot();
    for (int i = 0; i < 129; ++i) len_count_[i] = 0;
    count_ = 0;
}

void Fib::grow() {
    uint32_t ncap = (cap_ == 0) ? 4096u : cap_ * 2u;
    std::vector<Slot> old;
    old.swap(tbl_);
    uint32_t ocap = cap_;
    tbl_.assign(ncap, Slot());
    cap_ = ncap;
    mask_ = cap_ - 1;
    count_ = 0;
    for (uint32_t i = 0; i < ocap; ++i)
        if (old[i].len != EMPTY) store(old[i].len, old[i].hi, old[i].lo, old[i].hop);
}

uint32_t Fib::locate(uint32_t len, uint64_t hi, uint64_t lo) const {
    if (cap_ == 0) return EMPTY;
    uint32_t i = (uint32_t)(key_hash(len, hi, lo) & mask_);
    while (tbl_[i].len != EMPTY) {
        if (tbl_[i].len == len && tbl_[i].hi == hi && tbl_[i].lo == lo) return i;
        i = (i + 1) & mask_;
    }
    return EMPTY;
}

void Fib::store(uint32_t len, uint64_t hi, uint64_t lo, uint32_t hop) {
    uint32_t i = (uint32_t)(key_hash(len, hi, lo) & mask_);
    while (tbl_[i].len != EMPTY) {
        if (tbl_[i].len == len && tbl_[i].hi == hi && tbl_[i].lo == lo) {
            tbl_[i].hop = hop;
            return;
        }
        i = (i + 1) & mask_;
    }
    tbl_[i].len = len;
    tbl_[i].hi = hi;
    tbl_[i].lo = lo;
    tbl_[i].hop = hop;
    ++count_;
    ++len_count_[len];
}

void Fib::put(uint8_t len, uint64_t hi, uint64_t lo, uint32_t hop) {
    if (len > 128) return;
    uint64_t nhi, nlo;
    top_bits(len, hi, lo, nhi, nlo);
    if (cap_ == 0 || count_ * 5 >= cap_ * 3) grow();
    store(len, nhi, nlo, hop);
}

bool Fib::exact(uint8_t len, uint64_t hi, uint64_t lo, uint32_t& hop) const {
    uint64_t nhi, nlo;
    top_bits(len, hi, lo, nhi, nlo);
    uint32_t i = locate(len, nhi, nlo);
    if (i == EMPTY) return false;
    hop = tbl_[i].hop;
    return true;
}

bool Fib::longest_within(uint8_t maxlen, uint64_t hi, uint64_t lo, uint32_t& hop) const {
    for (int len = maxlen; len >= 0; --len) {
        if (len_count_[len] == 0) continue;
        uint64_t nhi, nlo;
        top_bits(len, hi, lo, nhi, nlo);
        uint32_t i = locate((uint32_t)len, nhi, nlo);
        if (i != EMPTY) { hop = tbl_[i].hop; return true; }
    }
    return false;
}
